function createWoodTexture(w,h){const c=document.createElement("canvas");c.width=w;c.height=h;const ctx=c.getContext("2d");const grad=ctx.createLinearGradient(0,0,w,0);grad.addColorStop(0,"#2a1d12");grad.addColorStop(0.3,"#331f10");grad.addColorStop(0.6,"#281a0e");grad.addColorStop(1,"#2a1d12");ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);for(let i=0;i<300;i++){const y=Math.random()*h;const alpha=0.02+Math.random()*0.08;ctx.strokeStyle=`rgba(${80+Math.random()*40},${50+Math.random()*25},${25+Math.random()*15},${alpha})`;ctx.lineWidth=0.3+Math.random()*2;ctx.beginPath();ctx.moveTo(0,y);for(let x=0;x<w;x+=6)ctx.lineTo(x,y+Math.sin(x*0.012+i)*2.5);ctx.stroke()}for(let i=0;i<8;i++){const y=Math.random()*h;ctx.fillStyle=`rgba(90,55,20,${0.04+Math.random()*0.04})`;ctx.fillRect(0,y,w,3+Math.random()*8)}for(let k=0;k<4;k++){const kx=Math.random()*w,ky=Math.random()*h;const grad2=ctx.createRadialGradient(kx,ky,0,kx,ky,10+Math.random()*8);grad2.addColorStop(0,"rgba(20,12,6,0.5)");grad2.addColorStop(0.5,"rgba(40,28,15,0.3)");grad2.addColorStop(1,"rgba(42,29,18,0)");ctx.fillStyle=grad2;ctx.fillRect(kx-25,ky-25,50,50)}return c}function createMarbleTexture(w,h){const c=document.createElement("canvas");c.width=w;c.height=h;const ctx=c.getContext("2d");const grad=ctx.createLinearGradient(0,0,w,h);grad.addColorStop(0,"#161422");grad.addColorStop(0.5,"#1a1828");grad.addColorStop(1,"#121020");ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);for(let pass=0;pass<3;pass++){const colors=["rgba(80,70,70,","rgba(60,55,55,","rgba(100,90,85,"];for(let v=0;v<30;v++){ctx.strokeStyle=colors[pass]+(0.03+Math.random()*0.06)+")";ctx.lineWidth=0.3+Math.random()*2;ctx.beginPath();let x=Math.random()*w,y=Math.random()*h;ctx.moveTo(x,y);for(let s=0;s<20;s++){x+=(Math.random()-0.5)*35;y+=(Math.random()-0.5)*35;ctx.lineTo(x,y)}ctx.stroke()}}for(let i=0;i<60;i++){const sx=Math.random()*w,sy=Math.random()*h;ctx.fillStyle=`rgba(210,210,220,${0.01+Math.random()*0.02})`;ctx.beginPath();ctx.arc(sx,sy,1+Math.random()*3,0,Math.PI*2);ctx.fill()}return c}function createBrickTexture(w,h){const c=document.createElement("canvas");c.width=w;c.height=h;const ctx=c.getContext("2d");const base=ctx.createLinearGradient(0,0,w,h);base.addColorStop(0,"#0a0a0a");base.addColorStop(0.3,"#0d0d0d");base.addColorStop(0.6,"#080808");base.addColorStop(1,"#0b0b0b");ctx.fillStyle=base;ctx.fillRect(0,0,w,h);ctx.save();ctx.globalCompositeOperation="lighter";for(let pass=0;pass<4;pass++){const veinCount=6+pass*3;for(let v=0;v<veinCount;v++){const alpha=0.012+Math.random()*0.022;const lw=0.4+Math.random()*(pass<2?2.5:0.8);const grey=180+Math.random()*75;ctx.strokeStyle=`rgba(${grey},${grey},${grey},${alpha})`;ctx.lineWidth=lw;ctx.beginPath();let x=Math.random()*w;let y=Math.random()*h;ctx.moveTo(x,y);const steps=18+Math.floor(Math.random()*14);for(let s=0;s<steps;s++){x+=(Math.random()-0.38)*(w/5);y+=(Math.random()-0.5)*(h/6);ctx.lineTo(x,y)}ctx.stroke()}}ctx.restore();for(let v=0;v<40;v++){const alpha=0.008+Math.random()*0.015;ctx.strokeStyle=`rgba(200,200,210,${alpha})`;ctx.lineWidth=0.3+Math.random()*0.5;ctx.beginPath();let x=Math.random()*w,y=Math.random()*h;ctx.moveTo(x,y);for(let s=0;s<10;s++){x+=(Math.random()-0.4)*30;y+=(Math.random()-0.5)*20;ctx.lineTo(x,y)}ctx.stroke()}for(let i=0;i<120;i++){const sx=Math.random()*w,sy=Math.random()*h;const bright=160+Math.random()*95;ctx.fillStyle=`rgba(${bright},${bright},${bright+10},${0.018+Math.random()*0.025})`;ctx.beginPath();ctx.arc(sx,sy,0.4+Math.random()*1.2,0,Math.PI*2);ctx.fill()}const sheen=ctx.createLinearGradient(0,h*0.25,w,h*0.55);sheen.addColorStop(0,"rgba(255,255,255,0)");sheen.addColorStop(0.35,"rgba(255,255,255,0.018)");sheen.addColorStop(0.5,"rgba(255,255,255,0.032)");sheen.addColorStop(0.65,"rgba(255,255,255,0.014)");sheen.addColorStop(1,"rgba(255,255,255,0)");ctx.fillStyle=sheen;ctx.fillRect(0,0,w,h);for(let i=0;i<8;i++){const cx2=Math.random()*w,cy2=Math.random()*h;const r=40+Math.random()*80;const patch=ctx.createRadialGradient(cx2,cy2,0,cx2,cy2,r);const isDark=Math.random()>0.45;if(isDark){patch.addColorStop(0,`rgba(0,0,0,${0.04+Math.random()*0.05})`)}else{patch.addColorStop(0,`rgba(30,30,32,${0.025+Math.random()*0.03})`)}patch.addColorStop(1,"rgba(0,0,0,0)");ctx.fillStyle=patch;ctx.fillRect(cx2-r,cy2-r,r*2,r*2)}return c}function createClubWallTexture(w,h){const c=document.createElement("canvas");c.width=w;c.height=h;const ctx=c.getContext("2d");ctx.fillStyle="#111014";ctx.fillRect(0,0,w,h);for(let i=0;i<4000;i++){const x=Math.random()*w;const y=Math.random()*h;const r=1.5+Math.random()*3.5;const v=14+Math.random()*12;const a=0.04+Math.random()*0.08;ctx.beginPath();ctx.ellipse(x,y,r,r*(0.5+Math.random()*0.8),Math.random()*Math.PI,0,Math.PI*2);ctx.fillStyle=`rgba(${v},${v-1},${v+2},${a})`;ctx.fill()}const dw=w/4,dh=h/5;ctx.save();ctx.filter="blur(2.5px)";for(let row=0;row<7;row++){const offset=row%2*(dw/2);for(let col=-1;col<6;col++){const dx=col*dw+offset+dw/2;const dy=row*dh+dh/2;ctx.strokeStyle="rgba(4,3,7,0.45)";ctx.lineWidth=3.5;ctx.beginPath();ctx.moveTo(dx,dy-dh/2);ctx.lineTo(dx+dw/2,dy);ctx.lineTo(dx,dy+dh/2);ctx.lineTo(dx-dw/2,dy);ctx.closePath();ctx.stroke()}}ctx.filter="none";ctx.restore();for(let row=0;row<7;row++){const offset=row%2*(dw/2);for(let col=-1;col<6;col++){const dx=col*dw+offset+dw/2;const dy=row*dh+dh/2;const pGrad=ctx.createRadialGradient(dx,dy-dh*0.1,0,dx,dy,dw*0.52);pGrad.addColorStop(0,"rgba(32,26,46,0.22)");pGrad.addColorStop(0.6,"rgba(16,13,24,0.10)");pGrad.addColorStop(1,"rgba(8,6,12,0)");ctx.fillStyle=pGrad;ctx.beginPath();ctx.moveTo(dx,dy-dh/2);ctx.lineTo(dx+dw/2,dy);ctx.lineTo(dx,dy+dh/2);ctx.lineTo(dx-dw/2,dy);ctx.closePath();ctx.fill();const bGrad=ctx.createRadialGradient(dx,dy,0,dx,dy,7);bGrad.addColorStop(0,"rgba(6,4,10,0.85)");bGrad.addColorStop(0.5,"rgba(18,14,26,0.35)");bGrad.addColorStop(1,"rgba(10,8,16,0)");ctx.fillStyle=bGrad;ctx.beginPath();ctx.arc(dx,dy,7,0,Math.PI*2);ctx.fill()}}const vGrad=ctx.createRadialGradient(w/2,h/2,w*0.2,w/2,h/2,w*0.75);vGrad.addColorStop(0,"rgba(20,17,30,0)");vGrad.addColorStop(1,"rgba(8,6,12,0.18)");ctx.fillStyle=vGrad;ctx.fillRect(0,0,w,h);return c}function createFloorTexture(w,h){const c=document.createElement("canvas");c.width=w;c.height=h;const ctx=c.getContext("2d");ctx.fillStyle="#080809";ctx.fillRect(0,0,w,h);const cols=2,rows=2;const tw=w/cols,th=h/rows;const groutW=Math.max(2,w*0.008);ctx.fillStyle="#040405";for(let i=0;i<=cols;i++)ctx.fillRect(i*tw-groutW/2,0,groutW,h);for(let j=0;j<=rows;j++)ctx.fillRect(0,j*th-groutW/2,w,groutW);for(let tx=0;tx<cols;tx++)for(let ty=0;ty<rows;ty++){const x0=tx*tw+groutW/2,y0=ty*th+groutW/2;const iw=tw-groutW,ih=th-groutW;const base=8+Math.random()*4;ctx.fillStyle=`rgb(${base},${base},${base+1})`;ctx.fillRect(x0,y0,iw,ih);ctx.save();ctx.globalAlpha=0.04;for(let v=0;v<3;v++){const vx=x0+Math.random()*iw;const vy=y0+Math.random()*ih;ctx.strokeStyle=`rgba(255,255,255,${0.03+Math.random()*0.04})`;ctx.lineWidth=0.5+Math.random()*1.5;ctx.beginPath();ctx.moveTo(vx,vy);ctx.quadraticCurveTo(vx+iw*0.3,vy+ih*(0.2+Math.random()*0.3),vx+iw*0.5,vy+ih*0.6);ctx.stroke()}ctx.restore();for(let s=0;s<120;s++){const sx=x0+Math.random()*iw,sy=y0+Math.random()*ih;const sv=Math.random()>0.5?14+Math.random()*6:4+Math.random()*4;ctx.fillStyle=`rgba(${sv},${sv},${sv},${0.06+Math.random()*0.08})`;ctx.fillRect(sx,sy,0.5+Math.random(),0.5+Math.random())}const hlGrad=ctx.createLinearGradient(x0,y0,x0,y0+ih*0.15);hlGrad.addColorStop(0,"rgba(255,255,255,0.02)");hlGrad.addColorStop(1,"rgba(255,255,255,0)");ctx.fillStyle=hlGrad;ctx.fillRect(x0,y0,iw,ih*0.15);const cg=ctx.createRadialGradient(x0+iw/2,y0+ih/2,0,x0+iw/2,y0+ih/2,iw*0.45);cg.addColorStop(0,"rgba(180,180,200,0.012)");cg.addColorStop(1,"rgba(0,0,0,0)");ctx.fillStyle=cg;ctx.fillRect(x0,y0,iw,ih)}return c}function createLeatherTexture(w,h){const c=document.createElement("canvas");c.width=w;c.height=h;const ctx=c.getContext("2d");ctx.fillStyle="#181418";ctx.fillRect(0,0,w,h);for(let i=0;i<4000;i++){const x=Math.random()*w,y=Math.random()*h;ctx.fillStyle=`rgba(${22+Math.random()*16},${18+Math.random()*14},${22+Math.random()*14},${0.2+Math.random()*0.35})`;ctx.beginPath();ctx.ellipse(x,y,1+Math.random()*2.5,0.5+Math.random()*1.8,Math.random()*Math.PI,0,Math.PI*2);ctx.fill()}return c}function createNormalFromCanvas(canvas){const{width:w,height:h}=canvas;const c=document.createElement("canvas");c.width=w;c.height=h;const srcCtx=canvas.getContext("2d");const ctx=c.getContext("2d");const srcData=srcCtx.getImageData(0,0,w,h).data;const img=ctx.createImageData(w,h);for(let y=0;y<h;y++){for(let x=0;x<w;x++){const i=(y*w+x)*4;const l=x>0?srcData[(y*w+(x-1))*4]:srcData[i];const r=x<w-1?srcData[(y*w+(x+1))*4]:srcData[i];const u=y>0?srcData[((y-1)*w+x)*4]:srcData[i];const d=y<h-1?srcData[((y+1)*w+x)*4]:srcData[i];img.data[i]=128+(l-r)*2;img.data[i+1]=128+(u-d)*2;img.data[i+2]=255;img.data[i+3]=255}}ctx.putImageData(img,0,0);return c}function canvasToTexture(canvas){const tex=new THREE.CanvasTexture(canvas);tex.wrapS=THREE.RepeatWrapping;tex.wrapT=THREE.RepeatWrapping;return tex}